package com.vandorlabs.neoforge.legacylanding;
import com.vandorlabs.redstone.ChannelList;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
/** Real configured Survival placement, permanent proxy ownership and cold stationary fallback. */
@net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs")
public final class NativeLegacyLandingChecks {
 private static ServerLevel world;private static net.neoforged.neoforge.common.util.FakePlayer actor;private static int ticks,stage,checks;private static boolean running;
 private static final NativeLegacyLandingKind[] KINDS={NativeLegacyLandingKind.WHEEL,NativeLegacyLandingKind.WHEEL,NativeLegacyLandingKind.SKI,NativeLegacyLandingKind.SKI,NativeLegacyLandingKind.STRUT,NativeLegacyLandingKind.ANGLED};
 private static final int[] SIZES={0,4,0,4,0,4};private static final UUID[] identities=new UUID[6];
 private static BlockPos pos(int n){return new BlockPos(144+n*8,112,8);}
 private static String phase(){return System.getProperty("vandorlabs.legacyLandingPhase","");}
 private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Legacy landing stage="+stage+" tick="+ticks+": "+why);}
 private static NativeLegacyLandingEntity root(int n){return NativeLegacyLandingBlock.owner(world,pos(n));}
 @net.neoforged.bus.api.SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent event){if(phase().isEmpty())return;try{world=event.getServer().overworld();for(int n=0;n<6;n++){var p=pos(n);for(int x=p.getX()-1;x<=p.getX()+1;x++){world.setChunkForced(x>>4,p.getZ()>>4,true);world.getChunkAt(new BlockPos(x,p.getY(),p.getZ()));}}actor=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(world);actor.setGameMode(GameType.SURVIVAL);running=true;}catch(Throwable failure){fail(failure);}}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post event){if(!running)return;try{ticks++;need(ticks<300,"bounded stationary journey "+Arrays.toString(Arrays.stream(KINDS).map(Enum::name).toArray()));if(ticks<15)return;if(phase().equals("read")){for(int n=0;n<6;n++){var root=root(n);need(root!=null&&root.kind()==KINDS[n]&&root.settings().size()==SIZES[n]&&root.progress()==2&&root.extended(),"cold exact configured root "+n);footprint(n);need(root.saveWithoutMetadata(world.registryAccess()).getCompound("ForgeCaps").getString("fixture").equals("retained"),"cold opaque legacy envelope "+n);}recovery(false);done();return;}
 if(stage==0){adventure();for(int n=0;n<6;n++)place(n);stage=1;return;}
 if(stage==1){for(int n=0;n<6;n++){approach(n);var root=root(n);identities[n]=root.identity();need(root.configure(actor,new NativeLegacyLandingData.Configuration(0,ChannelList.EMPTY,32,SIZES[n])),"manual selected footprint "+n);need(root.target(actor,true),"real target extension "+n);}stage=2;return;}
 if(stage==2){if(!all(2))return;for(int n=0;n<6;n++){footprint(n);need(root(n).identity().equals(identities[n]),"motion retains permanent owner "+n);approach(n);need(root(n).target(actor,false),"reversal admitted "+n);}stage=3;return;}
 if(stage==3){if(!all(0))return;for(int n=0;n<6;n++)footprint(n);approach(0);var at=pos(0).below(2);world.setBlock(at,Blocks.BEDROCK.defaultBlockState(),3);var old=root(0).saveWithFullMetadata(world.registryAccess());need(!root(0).target(actor,true)&&!root(0).extended()&&world.getBlockState(at).is(Blocks.BEDROCK),"foreign occupied future path refuses before target mutation");need(root(0).identity().equals(identities[0])&&root(0).progress()==0,"refused future path retains original owner/phase");world.removeBlock(at,false);for(int n=0;n<6;n++){approach(n);need(root(n).target(actor,true),"retry after actual obstruction removal "+n);}stage=4;return;}
 if(stage==4){if(!all(2))return;for(int n=0;n<6;n++){footprint(n);var root=root(n);var raw=root.saveWithoutMetadata(world.registryAccess());var opaque=new CompoundTag();opaque.putString("fixture","retained");raw.put("ForgeCaps",opaque);root.loadWithComponents(raw,world.registryAccess());need(!root.inert()&&root.saveWithoutMetadata(world.registryAccess()).getCompound("ForgeCaps").equals(opaque),"own choices plus opaque Source data retained "+n);var pick=new ItemStack(NativeLegacyLandingBindings.ITEMS.get(KINDS[n]));root.writeItem(pick);need(pick.has(net.minecraft.core.component.DataComponents.CUSTOM_DATA),"configured pick carries size/mode "+n);}
 var helper=pos(1).below();actor.setPos(helper.getX()+.5,helper.getY(),helper.getZ()-3);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND_PICKAXE));need(actor.hasCorrectToolForDrops(world.getBlockState(helper)),"legacy metal helper tool tag");need(actor.gameMode.destroyBlock(helper),"actual owned helper mining");var drops=world.getEntitiesOfClass(ItemEntity.class,new AABB(pos(1)).inflate(6));need(root(1)==null&&drops.size()==1&&drops.get(0).getItem().is(NativeLegacyLandingBindings.ITEMS.get(KINDS[1]))&&drops.get(0).getItem().getCount()==1,"helper mining leaves exactly one configured root drop");for(var drop:drops)drop.discard();place(1);need(root(1).configure(actor,new NativeLegacyLandingData.Configuration(0,ChannelList.EMPTY,32,4))&&root(1).target(actor,true),"restore one saved large owner");stage=5;return;}
 if(stage==5){if(!all(2))return;var raw=root(1).saveWithoutMetadata(world.registryAccess());var caps=new CompoundTag();caps.putString("fixture","retained");raw.put("ForgeCaps",caps);root(1).loadWithComponents(raw,world.registryAccess());recovery(true);done();}
 }catch(Throwable failure){fail(failure);}}
 private static void recovery(boolean install){var at=new BlockPos(136,112,8);world.setChunkForced(at.getX()>>4,at.getZ()>>4,true);world.getChunkAt(at);var expected=root(0).saveWithoutMetadata(world.registryAccess());var details=new CompoundTag();details.putString("Failure","exact failed rollback");var before=new ListTag();var cell=new CompoundTag();cell.putLong("Pos",at.below().asLong());cell.putString("Original","opaque retained source");before.add(cell);details.put("Before",before);expected.put("NativeLegacyLandingRecovery",details);var file=world.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("legacy-recovery-fixture.nbt");if(install)try{NbtIo.writeCompressed(expected,file);}catch(java.io.IOException failure){throw new IllegalStateException(failure);}else try{expected=NbtIo.readCompressed(file,NbtAccounter.create(2*1024*1024));}catch(java.io.IOException failure){throw new IllegalStateException(failure);}if(install){world.setBlock(at,NativeLegacyLandingBindings.BLOCKS.get(NativeLegacyLandingKind.WHEEL).defaultBlockState(),3);var tile=(NativeLegacyLandingEntity)world.getBlockEntity(at);tile.loadWithComponents(expected,world.registryAccess());need(tile.inert()&&sameRecovery(expected,tile.saveWithoutMetadata(world.registryAccess())),"failed recovery envelope remains inert and exact on installation");}else{var tile=(NativeLegacyLandingEntity)world.getBlockEntity(at);need(tile!=null&&tile.inert()&&sameRecovery(expected,tile.saveWithoutMetadata(world.registryAccess())),"cold failed recovery retains entire original snapshot and envelope");}}
 private static boolean sameRecovery(CompoundTag expected,CompoundTag actual){if(!expected.contains("keepPacked")&&actual.contains("keepPacked",Tag.TAG_BYTE)&&actual.getByte("keepPacked")==0)actual.remove("keepPacked");return expected.equals(actual);}
 private static void adventure(){var at=new BlockPos(136,108,8);world.setChunkForced(at.getX()>>4,at.getZ()>>4,true);world.getChunkAt(at);world.setBlock(at.below(),Blocks.STONE.defaultBlockState(),3);actor.setPos(at.getX()+.5,at.getY(),at.getZ()-3);var item=new ItemStack(com.vandorlabs.neoforge.seating.NativeSeatBindings.ITEMS.get(com.vandorlabs.neoforge.seating.NativeSeatKind.CHAIR));actor.setItemInHand(InteractionHand.MAIN_HAND,item);var placed=actor.gameMode.useItemOn(actor,world,item,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at.below()).add(0,.5,0),Direction.UP,at.below(),false));need(placed.consumesAction()&&item.isEmpty(),"ordinary seat setup for existing Adventure assertion");var chair=com.vandorlabs.neoforge.seating.NativeSeatBlock.owner(world,at);need(chair!=null,"Adventure setup has actual native chair");com.vandorlabs.neoforge.seating.NativeSeatRuntimeChecks.verifyAdventure(actor,chair);world.destroyBlock(at,false);}
 private static void approach(int n){var at=pos(n);actor.setPos(at.getX()+.5,at.getY()-1,at.getZ()-3);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);actor.setShiftKeyDown(false);}
 private static void place(int n){var p=pos(n);world.setBlock(p.above(),Blocks.STONE.defaultBlockState(),3);actor.setPos(p.getX()+.5,p.getY()-1,p.getZ()-3);actor.setYRot(Direction.SOUTH.toYRot());actor.setShiftKeyDown(false);var stack=new ItemStack(NativeLegacyLandingBindings.ITEMS.get(KINDS[n]));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);var result=actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(p.above()).add(0,-.5,0),Direction.DOWN,p.above(),false));need(result.consumesAction()&&stack.isEmpty()&&root(n)!=null,"actual supported Survival placement consumes one "+n);need(world.getBlockState(p.above()).is(Blocks.STONE),"mounting support retained "+n);}
 private static boolean all(float phase){for(int n=0;n<6;n++){var root=root(n);need(root!=null&&!root.inert(),"live physical root "+n);if(root.progress()!=phase){if(!root.error().isEmpty())throw new AssertionError("Refused scene "+n+" phase="+root.progress()+" error="+root.error());return false;}}return true;}
 private static void footprint(int n){var root=root(n);for(var offset:com.vandorlabs.gear.core.LegacyLandingLayout.reserved(Math.max(root.progress(),root.targetDistance()),SIZES[n])){var at=pos(n).offset(offset.x,offset.y,offset.z);need(NativeLegacyLandingBlock.owner(world,at)==root,"every reserved helper resolves one physical UUID "+n+" "+at);need(root.identity().equals(((NativeLegacyLandingEntity)world.getBlockEntity(at)).identity()),"new helper identity "+n);}need(!root.shape().cell(BlockPos.ZERO).isEmpty(),"authored mount collision exists "+n);}
 private static void done(){running=false;world.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][legacy-landing] "+phase()+" PASS checks="+checks+" actualSurvival/oneOwner/retainedSupports/motion/reversal/refusal/retry/configuredDrop/opaque/cold");world.getServer().halt(false);}
 private static void fail(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][legacy-landing] "+phase()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
 private NativeLegacyLandingChecks(){}
}
